function MakePalindrome(str: string): string;
begin
  var postfix := '';
  for var i := str.Length downto 1 do
  begin
    var suffix := str.Substring(i);
    if IsPalindrome(suffix) then
    begin
      postfix := suffix;
      break;
    end;
  end;
  Result := str + ReverseString(postfix);
end;


