function Factorize(n: integer): array of integer;
begin
  var factors := new List<integer>;
  var num := n;

  for var i := 2 to n.Sqrt do
  begin
    while (num mod i = 0) and (factors.Contains(i) = false) do
    begin
      factors.Add(i);
      num := num div i;
    end;
  end;

  if num > 1 then
    factors.Add(num);

  Result := factors.ToArray;
end;


