function SortThird(l: array of integer): array of integer;
begin
  var third := new List<integer>;
  var other := new List<integer>;
  var divisible := new List<integer>;

  for var i := 0 to l.Length - 1 do
  begin
    if i mod 3 = 0 then
      divisible.Add(l[i])
    else
      other.Add(l[i]);
  end;

  divisible.Sort;

  var j := 0;
  for var i := 0 to l.Length - 1 do
  begin
