function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s: string): string;
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;
{ prime_fib returns n-th number that is a Fibonacci number and it's also prime. }
begin
  var fib := new List<integer>;
  fib.Add(0);
  fib.Add(1);
  var i := 2;
  while fib.Count < n do
  begin
    fib.Add(fib[i-1] + fib[i-2]);
    i += 1;
  end;
  Result := fib[n-1];
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToList;
  sorted.Sort;

  for var i := 0 to sorted.Count - 3 do
  begin
    var left := i + 1;
    var right := sorted.Count - 1;

    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];

      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;

  Result := False;
end;


