function Fib4(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 0
  else
  begin
    var a := 0;
    var b := 0;
    var c := 2;
    var d := 0;
    for var i := 4 to n do
    begin
      d := a + b + c + d;
      a := b;
      b := c;
      c := d;
    end;
    Result := d;
  end;
end;


