function EncodeShift(s : string): string;
{ returns encoded string by shifting every character by 5 in the alphabet. }
begin
  Result := '';
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    Result += Chr(((Ord(ch) + 5 - Ord('a')) mod 26) + Ord('a'));
  end;
end;
function DecodeShift(s : string): string;
{ takes as input string encoded with encode_shift function. Returns decoded string. }
begin
  Result := '';
  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    Result += Chr(((Ord(ch) - Ord('a') - 5 + 26) mod 26) + Ord('a'));
  end;
end;


