function SameChars(s0, s1: string): boolean;
begin
  var s0Dict := new Dictionary<char, integer>;
  var s1Dict := new Dictionary<char, integer>;

  foreach var ch in s0 do
    if s0Dict.ContainsKey(ch) then
      s0Dict[ch] += 1
    else
      s0Dict[ch] := 1;

  foreach var ch in s1 do
    if s1Dict.ContainsKey(ch) then
      s1Dict[ch] += 1
    else
      s1Dict[ch] := 1;

  Result := s0Dict.Count = s1Dict.Count;

  foreach var kv in s0Dict do
    if not s1Dict.ContainsKey(kv.Key) or (s1Dict[kv.Key] <> kv.Value) then
    begin
      Result := False;
      exit;
    end;

  foreach var kv in s1Dict do
    if not s0Dict.ContainsKey(kv.Key) or (s0Dict[kv.Key] <> kv.Value) then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;


