    else
      count[num] := 1;

  var maxVal := -1;
  foreach var kv in count do
    if kv.Value >= kv.Key then
      if (kv.Key > maxVal) or ((kv.Key = maxVal) and (kv.Value > maxVal)) then
        maxVal := kv.Key;

  Result := maxVal;
end;


