function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n + 1, n + 1];
  for var i := 0 to n do
    dp[i, n] := n - i;
  for var j := n - 1 downto 0 do
  begin
    var m := n - j;
    for var i := m - 1 downto 0 do
    begin
      if arr[i] = arr[m - 1 - j] then
        dp[i, m] := dp[i + 1, m - 1]
      else
        dp[i, m] := Min(dp[i + 1, m], dp[i, m - 1]) + 1;
    end;
  end;
  Result := dp[0, n - 1];
end;


