  var encrypted := '';
  foreach var ch in s do
  begin
    if ch.IsLetter then
    begin
      var asciiVal := Ord(ch);
      if (asciiVal >= 65) and (asciiVal <= 90) then
        encrypted += Chr((asciiVal - 65 + 2) mod 26 + 65)
      else if (asciiVal >= 97) and (asciiVal <= 122) then
        encrypted += Chr((asciiVal - 97 + 2) mod 26 + 97)
      else
        encrypted += ch;
    end
    else
      encrypted += ch;
  end;
  Result := encrypted;
end;


