function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var buckets := new integer[m, n];
  var count := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i, j] = 1 then
      begin
        var minVal := Max(0, buckets[i, j] - 1);
        var maxVal := Min(capacity, buckets[i, j]);
        count += maxVal - minVal;
        buckets[i, j] := maxVal;
      end;
    end;

  Result := count;
end;


