function GetClosestVowel(word: string): string;
begin
  var vowels := 'aeiouAEIOU';
  var vowelList := new List<char>;
  var consonants := new List<char>;
  var consonantList := new List<char>;
  var vowelIndex := -1;
  var consonantIndex := -1;
  var minDistance := integer.MaxValue;
  var minVowel := #0;
  var minConsonant := #0;

  for var i := 1 to word.Length - 1 do
  begin
    var ch := word[i];
    if vowels.Contains(ch) then
    begin
      vowelList.Add(ch);
      if (vowelIndex = -1) and (vowelList.Count > 1) then
        vowelIndex := i;
    end
    else if not char.IsWhiteSpace(ch) then
    begin
      consonantList.Add(ch);
      if (consonantIndex = -1) and (consonantList.Count > 1) then
        consonantIndex := i;
    end;
  end;

  if vowelList.Count > 0 then
  begin
    minVowel := vowelList[0];
    minDistance := integer.MaxValue;
    for var i := 1 to vowelList.Count - 1 do
    begin
      var distance := Abs(vowelList[i].ToLower.CompareTo(vowelList[i-1].ToLower));
      if distance < minDistance then
      begin
        minDistance := distance;
        minVowel := vowelList[i];
      end;
    end;
  end;

  if consonantList.Count > 0 then
  begin
    minConsonant := consonantList[0];
    minDistance := integer.MaxValue;
    for var i := 1 to consonantList.Count - 1 do
    begin
      var distance := Abs(consonantList[i].ToLower.CompareTo(consonantList[i-1].ToLower));
      if distance < minDistance then
      begin
        minDistance := distance;
        minConsonant := consonantList[i];
      end;
    end;
  end;

  if (vowelList.Count > 0) and (consonantList.Count > 0) then
  begin
    if Abs(vowelIndex - consonantIndex) < minDistance then
    begin
      minDistance := Abs(vowelIndex - consonantIndex);
      minVowel := vowelList[0];
