function MatchParens(lst: array of string): string;
begin
  var s := lst.JoinToString;
  var stack := new Stack<char>;
  var good := True;

  for var i := 1 to s.Length do
  begin
    var c := s[i];
    if c = '(' then
      stack.Push(c)
    else
    begin
      if stack.Count = 0 then
      begin
        good := False;
        break;
      end
      else
        stack.Pop;
    end;
  end;

  if stack.Count > 0 then
    good := False;

  Result := if good then 'Yes' else 'No';
end;


