function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var product := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    sign := sign * (num > 0) - (num < 0);
    product := product * Abs(num);
    sum := sum + Abs(num);
  end;

  Result := sign * product;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  directions.Add((-1, 0));
  directions.Add((1, 0));
  directions.Add((0, -1));
  directions.Add((0, 1));
  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0));
  var res := new List<integer>;
  while queue.Count > 0 do
  begin
    var (x, y, cnt) := queue.Dequeue;
    if cnt = k then
    begin
      res.Add(grid[x, y]);
      break;
    end;
    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and not visited.Contains((nx, ny)) then
      begin
        visited.Add((nx, ny));
        queue.Enqueue((nx, ny, cnt + 1));
      end;
    end;
  end;
  res.Sort;
  Result := res.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var tri := new List<real>;
  tri.Add(3);
  if n = 0 then
  begin
    Result := tri.ToArray;
    exit;
  end;
  tri.Add(1);
  if n = 1 then
  begin
    Result := tri.ToArray;
    exit;
  end;
  tri.Add(2);
  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      tri.Add(tri[i - 1] + tri[i - 2] + tri[i - 3])
    else
      tri.Add(tri[i - 1] + tri[i - 2] + tri[i - 3] + 1);
  end;
  Result := tri.ToArray;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  var num := n;

  while num > 0 do
  begin
    var digit := num mod 10;
    if digit mod 2 <> 0 then
    begin
      product *= digit;
      hasOdd := True;
    end;
    num := num div 10;
  end;

  if hasOdd then
    Result := product
  else
    Result := 0;
end;


