    var isPrime := True;

    for var i := 2 to Trunc(Sqrt(length)) do
      if length mod i = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      primeWords.Add(word);
  end;

  var primeWordsStr := string.Join(' ', primeWords);
  Result := primeWordsStr;
end;


