function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 1 to operand.Length - 1 do
  begin
    case op[i-1] of
      '+': res += operand[i];
      '-': res -= operand[i];
      '*': res *= operand[i];
      '//': res := Trunc(res / operand[i]);
      '**': res := Round(Power(res, operand[i]));
    end;
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var isLetter := false;
  foreach var ch in s do
  begin
    if Char.IsLetter(ch) then
    begin
      isLetter := true;
      if Char.IsLower(ch) then
        sb.Append(Char.ToUpper(ch))
      else
        sb.Append(Char.ToLower(ch));
    end
    else
    begin
      isLetter := false;
      sb.Append(ch);
    end;
  end;
  if not isLetter then
    sb.Reverse;
  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;

  var hasher := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var inputBytes := System.Text.Encoding.ASCII.GetBytes(text);
  var hashBytes := hasher.ComputeHash(inputBytes);

  var sb := new System.Text.StringBuilder;
  for var i := 0 to hashBytes.Length - 1 do
    sb.Append(hashBytes[i].ToString('x2'));

  Result := sb.ToString;
end;


